-- GenDB engine variant Q11-from_permutation: template q11.sql, kind from_permutation (generated by generate.py; frozen)
SELECT
  ps_partkey,
  SUM(ps_supplycost * ps_availqty) AS value
FROM nation, supplier, partsupp
WHERE
  ps_suppkey = s_suppkey AND s_nationkey = n_nationkey AND n_name = $1
GROUP BY
  ps_partkey
HAVING
  SUM(ps_supplycost * ps_availqty) > (
    SELECT
      SUM(ps_supplycost * ps_availqty) * $2
    FROM nation, supplier, partsupp
    WHERE
      ps_suppkey = s_suppkey AND s_nationkey = n_nationkey AND n_name = $1
  )
ORDER BY
  value DESC
